/**
 * `agent/tools/*.ts`: typed tools and the built-in tools appended after them.
 */
import { join } from "node:path";
import { isToolEffect, } from "../../types.js";
import { builtinTools } from "../builtin-tools/index.js";
import { toolInputJsonSchema, toolOutputJsonSchema } from "../json-schema.js";
import { displayPath, errorMessage, isBlank } from "./context.js";
import { importDefault, moduleEntries } from "./modules.js";
export async function loadTools(ctx, toolsDir) {
    const tools = [];
    for (const { name, path } of await moduleEntries(ctx, toolsDir, "tool")) {
        const definition = await importDefault(ctx, path, "tool");
        if (definition === undefined) {
            continue;
        }
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
        const tool = compileTool(ctx, path, name, definition);
        if (tool !== undefined) {
            tools.push(tool);
        }
    }
    return tools;
}
/**
 * Validate one tool definition against the tool contract and convert its
 * schemas. Diagnostics point at `entryPath` (the authored file, or the
 * extension mount that contributed the tool).
 */
export function compileTool(ctx, entryPath, name, tool) {
    if (isBlank(tool.description)) {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, entryPath),
            message: "Tools require a non-empty description.",
        });
        return undefined;
    }
    const execution = tool.execution === "agent" ? "agent" : "server";
    const needsApprovalConfigured = tool.needsApproval === true || typeof tool.needsApproval === "function";
    const effect = declaredEffect(tool);
    if (execution === "agent") {
        if (isBlank(tool.script)) {
            ctx.diagnostics.push({
                severity: "error",
                path: displayPath(ctx, entryPath),
                message: 'Tools with execution: "agent" require a non-empty `script` (shell body; JSON on stdin, result on stdout).',
            });
            return undefined;
        }
        if (typeof tool.execute === "function") {
            ctx.diagnostics.push({
                severity: "warning",
                path: displayPath(ctx, entryPath),
                message: '`execute` is ignored when execution is "agent"; the Cursor agent runs `script` instead.',
            });
        }
        if (needsApprovalConfigured) {
            ctx.diagnostics.push({
                severity: "error",
                path: displayPath(ctx, entryPath),
                message: '`needsApproval` is only supported for execution: "server" tools (in-process).',
            });
            return undefined;
        }
    }
    else if (typeof tool.execute !== "function") {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, entryPath),
            message: 'Tools require an execute(input, ctx) function (or set execution: "agent" with a script).',
        });
        return undefined;
    }
    let inputSchema;
    try {
        inputSchema = toolInputJsonSchema(tool.inputSchema);
    }
    catch (error) {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, entryPath),
            message: `Failed to convert inputSchema to JSON Schema: ${errorMessage(error)}`,
        });
        return undefined;
    }
    let outputSchema;
    try {
        outputSchema = toolOutputJsonSchema(tool.outputSchema);
    }
    catch (error) {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, entryPath),
            message: `Failed to convert outputSchema to JSON Schema: ${errorMessage(error)}`,
        });
        return undefined;
    }
    return {
        name,
        description: tool.description,
        inputSchema,
        outputSchema,
        execution,
        needsApproval: needsApprovalConfigured,
        effect,
        script: execution === "agent" ? tool.script : undefined,
        definition: tool,
    };
}
/**
 * Static view of a tool's `effect` for the manifest: the literal when it is
 * one, `"dynamic"` for a per-call predicate, `undefined` when undeclared. A
 * malformed value is left undeclared rather than guessed — undeclared is the
 * safe state (a dry run stubs it), where a guess could be the unsafe one.
 */
function declaredEffect(tool) {
    if (typeof tool.effect === "function") {
        return "dynamic";
    }
    return isToolEffect(tool.effect) ? tool.effect : undefined;
}
/**
 * Append enabled built-in tools after authored tools. Authored tools with
 * the same name win.
 */
export function appendBuiltinTools(ctx, agentDir, tools, config) {
    const builtin = builtinTools(config);
    if (builtin.length === 0) {
        return;
    }
    const agentPath = displayPath(ctx, join(agentDir, "agent.ts"));
    for (const tool of builtin) {
        const existing = tools.find((t) => t.name === tool.name);
        if (existing !== undefined) {
            const owner = existing.extension === undefined ? "Authored" : `Extension "${existing.extension}"`;
            ctx.diagnostics.push({
                severity: "warning",
                path: agentPath,
                message: `${owner} tool "${tool.name}" shadows the built-in tool of the same name; the built-in is skipped.`,
            });
            continue;
        }
        tools.push(tool);
    }
}
